function serializeFacets(rows) {
  if (!Array.isArray(rows)) throw new TypeError("rows must be a dense array");

  const pairs = [];
  const hasOwn = Object.prototype.hasOwnProperty;

  for (let i = 0; i < rows.length; i++) {
    if (!hasOwn.call(rows, i)) throw new TypeError("rows must be a dense array");

    const row = rows[i];
    if (
      row === null ||
      typeof row !== "object" ||
      (Object.getPrototypeOf(row) !== Object.prototype &&
        Object.getPrototypeOf(row) !== null)
    ) {
      throw new TypeError("each row must be an ordinary object");
    }

    const { name, values } = row;
    if (typeof name !== "string" || !Array.isArray(values)) {
      throw new TypeError("invalid row");
    }

    for (let j = 0; j < values.length; j++) {
      if (!hasOwn.call(values, j) || typeof values[j] !== "string") {
        throw new TypeError("values must be a dense string array");
      }

      pairs.push([encode(name), encode(values[j])]);
    }
  }

  pairs.sort((a, b) =>
    a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0
  );

  return pairs.map(([name, value]) => name + "=" + value).join("&");
}

function encode(value) {
  return encodeURIComponent(value).replace(/[!'()*]/g, (char) =>
    "%" + char.charCodeAt(0).toString(16).toUpperCase()
  );
}
